const ytTabId = 2052873298;

// Wait 4 seconds for video player to initialize
await new Promise(r => setTimeout(r, 4000));

// Check video element in page
const playerStatus = await browserjs(ytTabId, () => {
  const video = document.querySelector("video");
  if (!video) return { found: false };
  return {
    found: true,
    currentTime: video.currentTime,
    duration: video.duration,
    paused: video.paused,
    readyState: video.readyState,
    muted: video.muted,
    title: document.title
  };
});
console.log("Player status:", playerStatus);

// If paused, trigger play
if (playerStatus.found && playerStatus.paused) {
  await browserjs(ytTabId, () => {
    const video = document.querySelector("video");
    if (video) video.play();
  });
  await new Promise(r => setTimeout(r, 2000));
}

